const assert = require('node:assert/strict');
const { test } = require('node:test');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const { run } = require('./app');

test('type0 through type29 multiply by 1 through 30', () => {
  for (let index = 0; index < 30; index++) {
    for (const x of [0, -0, 1, -7, 2.5, Number.MAX_VALUE]) {
      assert.equal(run({ kind: `type${index}`, x }), x * (index + 1));
    }
  }
});

test('bonus doubles x before adding five', () => {
  for (const x of [0, -0, 1, -7, 2.5, Number.MAX_VALUE]) {
    assert.equal(run({ kind: 'bonus', x }), x * 2 + 5);
  }
});

test('only exact supported kind strings are accepted', () => {
  for (const kind of [undefined, null, 0, {}, ['type0'], 'type-1', 'type30',
    'type01', 'type1.0', 'type0\n', 'TYPE0', ' bonus', 'toString', '__proto__']) {
    assert.throws(() => run({ kind, x: 1 }), { message: 'kind' });
  }
});

test('x must be a finite number, and is validated before kind', () => {
  for (const x of [undefined, null, '2', true, {}, [], 2n, NaN, Infinity, -Infinity]) {
    for (const kind of ['type0', 'type29', 'bonus', 'unknown']) {
      assert.throws(() => run({ kind, x }), { message: 'x' });
    }
  }
});

function invokeCli(input) {
  return spawnSync(process.execPath, [path.join(__dirname, 'cli.js'), JSON.stringify(input)], {
    encoding: 'utf8',
  });
}

test('CLI retains JSON argument and output behavior for all kinds', () => {
  for (const kind of [...Array.from({ length: 30 }, (_, i) => `type${i}`), 'bonus']) {
    const result = invokeCli({ kind, x: 2.5 });
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, `${JSON.stringify(run({ kind, x: 2.5 }))}\n`);
  }
});

test('CLI fails for invalid kind and x', () => {
  for (const input of [{ kind: 'unknown', x: 1 }, { kind: 'bonus', x: '1' }]) {
    const result = invokeCli(input);
    assert.equal(result.status, 1);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, new RegExp(`Error: ${input.kind === 'unknown' ? 'kind' : 'x'}`));
  }
});

